begin;

update public.global_recipe_catalog set steps='[{"text":{"ru":"Замаринуйте морковь и дайкон в рисовом уксусе с сахаром и тёплой водой на 60 минут."},"minutes":60},{"text":{"ru":"Свинину нарежьте тонкими ломтиками, смешайте с рыбным соусом и частью сахара, оставьте на 20 минут."},"minutes":20},{"text":{"ru":"Обжарьте свинину на сильном огне до карамельной корочки и полной готовности."},"minutes":8},{"text":{"ru":"Прогрейте багет, разрежьте вдоль, нанесите паштет и майонез."},"minutes":6},{"text":{"ru":"Выложите свинину, хорошо отжатые маринованные овощи, свежий огурец, кинзу и чили. Плотно закройте сэндвич и сразу отпускайте."},"minutes":4}]'::jsonb where id='df676885-dd72-4d4e-b7f9-0248aae4f21b';
update public.global_recipe_catalog set steps='[{"text":{"ru":"Мякиш замочите в холодной воде на 10 минут и тщательно отожмите."},"minutes":10},{"text":{"ru":"Измельчите помидоры, очищенный огурец, зелёный перец, чеснок и хлеб до полностью однородной массы."},"minutes":3},{"text":{"ru":"Не выключая блендер, тонкой струёй введите оливковое масло до получения устойчивой эмульсии."},"minutes":2},{"text":{"ru":"Добавьте хересный уксус и соль, отрегулируйте вкус. При необходимости процедите через мелкое сито."},"minutes":4},{"text":{"ru":"Охладите не менее 2 часов. Перед подачей перемешайте и подавайте холодным."},"minutes":120}]'::jsonb where id='cae56ed3-5cc6-4eb7-91ab-b391b164495b';
update public.global_recipe_catalog set steps='[{"text":{"ru":"Нарежьте зелёный перец кольцами и обжарьте в смеси сливочного и оливкового масла до мягкости."},"minutes":4},{"text":{"ru":"Добавьте очищенные и нарезанные помидоры, посолите и тушите до испарения лишней влаги и отделения масла по краям."},"minutes":10},{"text":{"ru":"Убавьте огонь и аккуратно разбейте яйца прямо в томатно-перечную основу."},"minutes":2},{"text":{"ru":"Перемешайте яйца всего 2–3 раза, сохраняя заметные кусочки белка и желтка; не превращайте смесь в мелкую крошку."},"minutes":3},{"text":{"ru":"Снимите с огня, когда белок схватится, а желток останется мягким. Посыпьте хлопьями пуль бибер, орегано и брынзой. Подавайте сразу."},"minutes":2}]'::jsonb where id='c6082f67-ce4d-4597-9c90-8324a1f31ec6';
update public.global_recipe_catalog set steps='[{"text":{"ru":"Промойте красную чечевицу до прозрачной воды. Нарежьте лук, морковь и картофель небольшими кусочками."},"minutes":6},{"text":{"ru":"Обжарьте лук и морковь в части сливочного масла до мягкости, затем добавьте томатную пасту и прогрейте её до более тёмного оттенка."},"minutes":8},{"text":{"ru":"Добавьте чечевицу, картофель и воду или бульон. Доведите до кипения и варите на слабом огне до полного разваривания чечевицы."},"minutes":25},{"text":{"ru":"Пробейте суп блендером до гладкого пюре. При необходимости разбавьте кипятком до консистенции густых сливок."},"minutes":4},{"text":{"ru":"Растопите оставшееся масло, снимите с огня и смешайте с мятой и паприкой. Разлейте суп и сверху добавьте ароматное масло."},"minutes":4},{"text":{"ru":"Подавайте горячим с долькой лимона."},"minutes":1}]'::jsonb where id='a2c2bbc5-01ef-4e72-89f3-8f6e4b058e32';
update public.global_recipe_catalog set steps='[{"text":{"ru":"Промойте листья базилика в холодной воде и полностью обсушите. Охладите ступку и пестик."},"minutes":5},{"text":{"ru":"Растолките чеснок с крупной солью до однородной пасты."},"minutes":2},{"text":{"ru":"Добавьте кедровые орехи и разотрите до кремовой консистенции."},"minutes":3},{"text":{"ru":"Порциями добавляйте базилик и прижимными круговыми движениями растирайте листья о стенки ступки, не нагревая массу."},"minutes":6},{"text":{"ru":"Вмешайте пармезан и пекорино, затем тонкой струёй добавьте оливковое масло до густого однородного соуса. Храните охлаждённым и используйте без нагрева."},"minutes":5}]'::jsonb where id='6ed2b35f-4a84-4b8d-92d4-003ded794264';
update public.global_recipe_catalog set steps='[{"text":{"ru":"Разотрите хлопья чили с солью и мальдивской рыбой до грубой пасты."},"minutes":4},{"text":{"ru":"Добавьте мелко нарезанный красный лук и продолжайте растирать, чтобы лук отдал сок."},"minutes":3},{"text":{"ru":"Вмешайте тёртый кокос и тщательно разотрите руками до равномерного распределения специй."},"minutes":5},{"text":{"ru":"Добавьте свежевыжатый сок лайма и перемешайте до однородности."},"minutes":2},{"text":{"ru":"Дайте самболу постоять 5 минут, повторно перемешайте и подавайте свежим к рису, карри или другим горячим блюдам."},"minutes":5}]'::jsonb where id='39d2a352-48f7-450f-828b-965420b3b83a';
update public.global_recipe_catalog set steps='[{"text":{"ru":"Используйте рыбу, предназначенную для сырого употребления. Нарежьте её ровными кубиками около 2 см и держите охлаждённой до момента сборки."},"minutes":5},{"text":{"ru":"Лук нарежьте очень тонкими перьями, замочите в ледяной воде на 10 минут и тщательно обсушите."},"minutes":10},{"text":{"ru":"Выжмите сок лаймов, избегая избыточного давления на кожуру. Кинзу и перец мелко нарежьте."},"minutes":5},{"text":{"ru":"Посолите рыбу, добавьте перец и кинзу, залейте соком лайма и выдержите только 3–5 минут, пока края кубиков не побелеют."},"minutes":5},{"text":{"ru":"Добавьте лук, перемешайте один раз и сразу отпускайте. Подавайте с отварным бататом и кукурузой."},"minutes":2}]'::jsonb where id='bd77d535-c679-4bdb-9e31-e58ca3abea4a';
update public.global_recipe_catalog set steps='[{"text":{"ru":"Промойте булгур и залейте его соком лимона. Оставьте на 15 минут для набухания."},"minutes":15},{"text":{"ru":"Петрушку и мяту вымойте и очень тщательно обсушите. Удалите толстые стебли и мелко порубите зелень ножом."},"minutes":12},{"text":{"ru":"Помидоры нарежьте мелким кубиком и дайте лишнему соку стечь в отдельную ёмкость."},"minutes":5},{"text":{"ru":"Мелко нарежьте зелёный лук, соедините с зеленью, булгуром и помидорами."},"minutes":4},{"text":{"ru":"Добавьте сок второго лимона, оливковое масло, соль и душистый перец. Перемешайте и выдержите 10 минут перед отпуском."},"minutes":10}]'::jsonb where id='3b8c9433-c3e0-44e7-bd9f-55bcef56af1a';
update public.global_recipe_catalog set steps='[{"text":{"ru":"Сушёный орегано разотрите между ладонями и залейте винным уксусом на 5 минут."},"minutes":5},{"text":{"ru":"Петрушку и чеснок мелко порубите ножом, не превращая их в гладкое пюре."},"minutes":8},{"text":{"ru":"Смешайте зелень, чеснок, орегано с уксусом и хлопья чили."},"minutes":3},{"text":{"ru":"Влейте оливковое масло тонкой струёй и перемешайте до равномерного распределения компонентов."},"minutes":2},{"text":{"ru":"Добавьте растворённую в тёплой воде соль. Выдержите соус не менее 2 часов, затем повторно перемешайте перед подачей."},"minutes":120}]'::jsonb where id='7124f65e-2653-49b2-b09c-11975025eb1e';
update public.global_recipe_catalog set steps='[{"text":{"ru":"Вымойте и обсушите свежие овощи. Красный перец при необходимости обожгите до потемнения кожицы, накройте и очистите."},"minutes":20},{"text":{"ru":"Помидоры и огурцы нарежьте крупными кусочками около 2 см, очищенный перец — полосками."},"minutes":8},{"text":{"ru":"Лук нарежьте тонкими кольцами, петрушку мелко порубите."},"minutes":4},{"text":{"ru":"Соедините овощи, лук и петрушку, добавьте соль, масло и винный уксус. Перемешайте бережно."},"minutes":3},{"text":{"ru":"Выложите салат на блюдо горкой, сверху равномерно распределите мелко натёртую брынзу и украсьте оливками. Не перемешивайте после добавления сыра."},"minutes":3}]'::jsonb where id='6c21c47a-a27c-4b57-8c25-cbb535ffe72e';
update public.global_recipe_catalog set description='Пицца Маргарита на тонкой основе с томатной основой, моцареллой, свежим помидором и растительным маслом.', steps='[{"text":{"ru":"Смешайте пшеничную муку с солью, постепенно добавьте воду до получения мягкого эластичного теста. Вымесите до гладкости."},"minutes":8},{"text":{"ru":"Накройте тесто и оставьте на 30–60 минут, чтобы оно отдохнуло и стало пластичным."},"minutes":45},{"text":{"ru":"Растяните тесто в круглую основу толщиной около 3–5 мм и перенесите на горячий противень или камень."},"minutes":5},{"text":{"ru":"Нанесите тонкий слой томатного соуса, распределите моцареллу и ломтики помидора, затем слегка сбрызните маслом."},"minutes":3},{"text":{"ru":"Выпекайте в предварительно максимально разогретой духовке при 230–250 °C до золотистой корочки основы и полного расплавления сыра."},"minutes":10},{"text":{"ru":"Дайте пицце постоять 1–2 минуты, нарежьте и отпускайте горячей."},"minutes":2}]'::jsonb where id='10b5d57c-c0eb-4c59-9805-b2734dae88c1';
update public.global_recipe_catalog set base_servings=case when yield_unit='pcs' and yield_quantity is not null then greatest(1,yield_quantity) else 1 end where is_active=true and base_servings is null;
commit;